const css=`:root{font-family:system-ui,sans-serif;color:#203b36;background:#f4f3ef}*{box-sizing:border-box}body{margin:0}button,input,textarea{font:inherit}button,a{touch-action:manipulation}button{min-height:42px;padding:9px 13px;border:1px solid #b7c6bd;border-radius:9px;color:#245248;background:#fff;cursor:pointer}button:disabled{opacity:.5;cursor:default}button:focus-visible,a:focus-visible,input:focus-visible,textarea:focus-visible{outline:3px solid #d99127;outline-offset:2px}.primary{background:#245248;color:#fff}.bar{position:sticky;top:0;z-index:2;display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:12px;padding:15px 22px;background:#fff;border-bottom:1px solid #d3ddd5}.bar .result-notice{flex-basis:100%;margin:0}.brand{font-weight:750;letter-spacing:.08em}.layout{display:grid;grid-template-columns:235px minmax(0,1fr) 330px;min-height:calc(100vh - 75px);max-width:1700px;margin:auto}.sidebar,.detail{padding:22px 18px}.sidebar{border-right:1px solid #d3ddd5}.detail{border-left:1px solid #d3ddd5;background:#eef1eb}.conversation{padding:26px;min-width:0}h1{font-size:30px;margin:0 0 12px}h2{font-size:19px}h3{font-size:16px}p{line-height:1.7;white-space:pre-wrap;overflow-wrap:anywhere}.muted{color:#587067;font-size:14px}.notice{padding:12px 16px;margin:15px 0;border:1px solid #ddc797;border-radius:10px;background:#fff4dc}.card{padding:18px;border:1px solid #d4ded6;border-radius:13px;background:#fff;margin:14px 0}.message{padding:17px 20px;background:#fff;border:1px solid #d4ded6;border-radius:12px;margin:14px 0}.message p{margin:9px 0}.project-list{display:flex;flex-direction:column;gap:9px;margin:16px 0}.project-list button{text-align:left;overflow-wrap:anywhere}.selected{background:#e0e9df;border-color:#7b9c89}.actions{display:flex;gap:9px;align-items:center;flex-wrap:wrap}.tabs{display:flex;gap:4px;flex-wrap:wrap;border-bottom:1px solid #bdcdbf;padding-bottom:12px}.tabs button{min-width:48px;padding:9px}.tabs [aria-selected=true]{background:#245248;color:#fff}.composer label{display:block;margin:14px 0 6px}.composer input,.composer textarea{width:100%;padding:11px;border:1px solid #b4c5b9;border-radius:9px;background:#fff;color:#203b36}.attachments{min-width:0}.attachments button{max-width:100%;overflow-wrap:anywhere}.attachments input[type=file]{max-width:100%}.composer input[type=checkbox]{width:18px;height:18px;padding:0;vertical-align:middle;margin-right:8px}.composer textarea{min-height:155px;resize:vertical;line-height:1.7}.status{font-size:14px;color:#587067;min-height:24px}.hash{font-family:ui-monospace,monospace;font-size:12px;overflow-wrap:anywhere}dl{display:grid;grid-template-columns:auto minmax(0,1fr);gap:10px}dd{margin:0;overflow-wrap:anywhere}summary{cursor:pointer;padding:8px 0}.mobile-nav{display:none}.danger{color:#8a3826}a{color:#245248}.planning{min-width:0}.planning nav{display:flex;gap:10px;align-items:center;flex-wrap:wrap}.planning .card{padding:13px}.planning h4{margin-bottom:8px}.planning button{max-width:100%;overflow-wrap:anywhere}.planning article{margin:14px 0}.source-links{display:flex;gap:6px;flex-wrap:wrap}.source-text{white-space:pre-wrap;overflow-wrap:anywhere;font:inherit;line-height:1.7}.dag-scroll{max-width:100%;max-height:600px;overflow:auto;margin:12px 0}.dag-scroll svg{display:block;font-size:11px}.dag-scroll [role=button]{cursor:pointer}.dag-scroll [role=button]:focus-visible{outline:3px solid #d99127;outline-offset:2px}@media(max-width:1050px){.layout{grid-template-columns:200px minmax(0,1fr)}.detail{grid-column:2;border-left:0;border-top:1px solid #d3ddd5}}@media(max-width:700px){.bar{padding:12px 16px}.layout{display:block}.mobile-nav{display:flex;gap:7px;flex-wrap:wrap;width:100%}.layout [data-panel]{display:none}.layout [data-panel].visible{display:block}.sidebar,.detail{border:0;padding:20px 16px}.conversation{padding:22px 16px}h1{font-size:26px}.card{padding:16px}.bar .muted{width:100%}}`;
export function workbenchPage(value:WorkbenchBoot){
 const nonce=randomBytes(18).toString('base64url'),json=JSON.stringify(value).replaceAll('<','\\u003c').replaceAll('>','\\u003e').replaceAll('&','\\u0026').replaceAll('\u2028','\\u2028').replaceAll('\u2029','\\u2029');
 return {policy:`default-src 'none'; script-src 'nonce-${nonce}'; style-src 'nonce-${nonce}'; connect-src 'self'; frame-src 'none'; frame-ancestors 'self'; base-uri 'none'; object-src 'none'; worker-src 'none'; form-action 'none'`,html:`<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>工作台 · DevMesh</title><style nonce="${nonce}">${css}</style></head><body><div id="root"><main class="conversation"><h1>DevMesh 工作台</h1><p>正在加载工作台…</p><noscript>请启用JavaScript进入工作台。</noscript></main></div><script id="workbench-data" type="application/json" nonce="${nonce}">${json}</script><script defer nonce="${nonce}" src="/api/v1/workbench/client.js"></script></body></html>`};
}
