import type {Router,Request,Response,RequestHandler} from 'express';
import {readFile} from 'node:fs/promises';
import {randomBytes} from 'node:crypto';
import {z} from 'zod';
import {ids,opaqueKey,parseContract,idempotencyKey,candidateReviewEntry,candidateHumanResult,candidateRejectionResult,candidateReviewHistory,candidateRejectionHistory,recordCandidateReviewInput,recordCandidateRejectionInput} from '@devmesh/contracts';
import {StorageError} from '@devmesh/storage-sqlite';
import type {LocalContentStore} from '@devmesh/blob-store';
import type {Identity} from './index.js';

type Route=(handler:(request:Request,response:Response,identity:Identity)=>Promise<void>)=>RequestHandler;
const empty=z.strictObject({}),positive=z.string().regex(/^[1-9][0-9]*$/).transform(Number).pipe(z.number().int().safe()),historyQuery={afterSequence:z.string().regex(/^(0|[1-9][0-9]*)$/).transform(Number).pipe(z.number().int().safe()).optional(),limit:positive.pipe(z.number().max(100)).optional()};
const css=`:root{font-family:system-ui,sans-serif;color:#203b36;background:#f4f3ef}*{box-sizing:border-box}body{margin:0}main{max-width:1050px;margin:auto;padding:32px 24px 60px}h1{font-size:36px;margin:22px 0 10px}h2{font-size:21px}h3{font-size:17px}p{line-height:1.7;white-space:pre-wrap;overflow-wrap:anywhere}a{color:#205a4d}button,input,textarea,select{font:inherit}button{min-height:44px;padding:10px 16px;border-radius:10px;background:#fff;color:#205a4d;border:1px solid #b4c7bd;cursor:pointer}button:disabled{opacity:.5;cursor:default}.primary{background:#205a4d;color:#fff}button:focus-visible,a:focus-visible,input:focus-visible,textarea:focus-visible,select:focus-visible{outline:3px solid #d99127;outline-offset:2px}.row{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap}.muted{color:#536b64;font-size:14px}.card,.version{padding:22px;border:1px solid #d2ded7;border-radius:16px;background:#fff;margin:16px 0}.version{background:#e8eee6}.commit{font-family:ui-monospace,Consolas,monospace;overflow-wrap:anywhere}.notice{padding:14px 18px;background:#fff2d6;border:1px solid #e1cb8d;border-radius:12px}.badge{font-size:13px;padding:5px 10px;background:#edf1ef;border-radius:30px}.PASS{background:#e3f1e6}.FAIL,.STALE{background:#ffe9e4}label{display:block;margin:14px 0 6px;font-size:14px}textarea,input,select{display:block;max-width:100%;width:100%;border:1px solid #b6c8bc;border-radius:8px;padding:10px;background:#fff;color:#203b36}textarea{resize:vertical;min-height:90px}.actions{display:flex;gap:10px;flex-wrap:wrap;margin:16px 0}.pager{display:flex;gap:16px;align-items:center;margin:18px 0}summary{cursor:pointer;padding:8px 0}details{font-size:14px}.history{border-left:3px solid #ccdcd0;padding:0 16px;margin:16px 0}.expected{background:#f3f6f1;padding:12px 16px;border-radius:10px}.field-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}@media(max-width:600px){main{padding:24px 16px}h1{font-size:30px}.card,.version{padding:18px}.field-grid{grid-template-columns:1fr}}`;

export function mountReviewRoutes(router:Router,content:LocalContentStore,route:Route):void{
  const base='/runs/:runId/candidates/:candidateId/review';
  const subject=(request:Request,identity:Identity)=>({principalId:identity.principalId,runId:parseContract(ids.run,request.params.runId),candidateId:parseContract(ids.candidate,request.params.candidateId)});
  const guarded:Route=handler=>route(async(request,response,identity)=>{try{await handler(request,response,identity);}catch(error){const {code,status}=error as {code?:string;status?:number};if(error instanceof StorageError&&error.status===404)throw new StorageError('RESOURCE_NOT_FOUND',404,'Candidate is not visible');if(code?.startsWith('CANDIDATE_')||code?.startsWith('RELEASE_CANDIDATE_'))throw new StorageError(code==='CANDIDATE_REVIEW_LIMIT'?'LIMIT_EXCEEDED':'REVIEW_UNAVAILABLE',code==='CANDIDATE_REVIEW_LIMIT'?413:status===404?404:status===422?422:409,'Exact candidate review unavailable');throw error;}});
  async function entry(request:Request,identity:Identity){empty.parse(request.query);const who=subject(request,identity),candidate=await content.storage.request('getReleaseCandidate',who),review=await content.storage.request('getCandidateReview',who);return parseContract(candidateReviewEntry,{runId:who.runId,codeCommit:candidate.manifest.codeCommit,review});}
  router.get(base,guarded(async(request,response,identity)=>{const value=await entry(request,identity);response.setHeader('ETag',`"r${value.review.resourceRevision}"`);response.json(value);}));
  router.get(base+'/view',guarded(async(request,response,identity)=>{
    const value=await entry(request,identity),nonce=randomBytes(18).toString('base64url'),json=JSON.stringify(value).replaceAll('<','\\u003c').replaceAll('>','\\u003e').replaceAll('&','\\u0026').replaceAll('\u2028','\\u2028').replaceAll('\u2029','\\u2029');
    response.setHeader('Referrer-Policy','no-referrer');response.setHeader('Content-Security-Policy',`default-src 'none'; script-src 'nonce-${nonce}'; style-src 'nonce-${nonce}'; connect-src 'self'; frame-src 'none'; frame-ancestors 'self'; base-uri 'none'; object-src 'none'; worker-src 'none'; form-action 'none'`);
    response.type('text/html; charset=utf-8').send(`<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>候选审查 · DevMesh</title><style nonce="${nonce}">${css}</style></head><body><div id="root"><main><h1>候选审查</h1><p>正在加载审查项…</p><noscript>请启用JavaScript查看与记录审查。</noscript></main></div><script id="review-data" type="application/json" nonce="${nonce}">${json}</script><script defer nonce="${nonce}" src="/api/v1/runs/${encodeURIComponent(value.runId)}/candidates/${encodeURIComponent(value.review.candidateId)}/review/client.js"></script></body></html>`);
  }));
  router.get(base+'/client.js',guarded(async(request,response,identity)=>{await entry(request,identity);const bytes=await readFile(new URL('./web/review/review-client.js',import.meta.url));await entry(request,identity);response.type('application/javascript; charset=utf-8').send(bytes);}));
  const write=(request:Request,identity:Identity)=>{empty.parse(request.query);if(!request.is('application/json'))throw new StorageError('CONTENT_TYPE_INVALID',415,'Expected JSON');const who=subject(request,identity),match=request.headers['if-match'];return {meta:{principalId:identity.principalId,scopeId:who.runId,idempotencyKey:parseContract(idempotencyKey,request.headers['idempotency-key'])},runId:who.runId,candidateId:who.candidateId,...(match===undefined?{}:{ifMatch:parseContract(z.string().max(128),match)})};};
  router.post(base+'/results',guarded(async(request,response,identity)=>{const value=write(request,identity),body=parseContract(recordCandidateReviewInput,request.body);response.status(201).json(parseContract(candidateHumanResult,await content.storage.request('recordCandidateReview',{...value,...body})));}));
  router.post(base+'/rejections',guarded(async(request,response,identity)=>{const value=write(request,identity),body=parseContract(recordCandidateRejectionInput,request.body);response.status(201).json(parseContract(candidateRejectionResult,await content.storage.request('recordCandidateRejection',{...value,...body})));}));
  router.get(base+'/history',guarded(async(request,response,identity)=>{const query=parseContract(z.strictObject({...historyQuery,itemId:opaqueKey.optional()}),request.query);response.json(parseContract(candidateReviewHistory,await content.storage.request('listCandidateReviewHistory',{...subject(request,identity),...query})));}));
  router.get(base+'/rejections/history',guarded(async(request,response,identity)=>{const query=parseContract(z.strictObject({...historyQuery,rejectionId:opaqueKey.optional()}),request.query);response.json(parseContract(candidateRejectionHistory,await content.storage.request('listCandidateRejectionHistory',{...subject(request,identity),...query})));}));
}
