import {randomBytes} from 'node:crypto';
import type {z} from 'zod';
import type {acceptanceBasisView} from '@devmesh/contracts';

const css=`:root{font-family:system-ui,sans-serif;color:#203b36;background:#f4f3ef}*{box-sizing:border-box}body{margin:0}main{max-width:1050px;margin:auto;padding:32px 24px 60px}h1{font-size:36px;margin:22px 0 10px}h2{font-size:21px}p{line-height:1.7;white-space:pre-wrap;overflow-wrap:anywhere}a{color:#205a4d}button,input,textarea{font:inherit}button{min-height:44px;padding:10px 16px;border-radius:10px;background:#fff;color:#205a4d;border:1px solid #b4c7bd;cursor:pointer}button:disabled{opacity:.5;cursor:default}.primary{background:#205a4d;color:#fff}button:focus-visible,a:focus-visible,input:focus-visible,textarea:focus-visible{outline:3px solid #d99127;outline-offset:2px}.row,.actions{display:flex;align-items:center;gap:12px;flex-wrap:wrap}.row{justify-content:space-between}.actions{margin:16px 0}.muted{color:#536b64;font-size:14px}.card,.version{padding:22px;border:1px solid #d2ded7;border-radius:16px;background:#fff;margin:16px 0}.version{background:#e8eee6}.hash{font-family:ui-monospace,Consolas,monospace;overflow-wrap:anywhere;font-size:13px}.notice{padding:14px 18px;background:#fff2d6;border:1px solid #e1cb8d;border-radius:12px}.badge{font-size:13px;padding:5px 10px;background:#edf1ef;border-radius:30px}label{display:block;margin:14px 0;line-height:1.7}input[type=checkbox]{margin:0 10px 0 0;width:18px;height:18px;vertical-align:middle}textarea{display:block;width:100%;border:1px solid #b6c8bc;border-radius:8px;padding:10px;background:#fff;color:#203b36;resize:vertical;min-height:90px}summary{cursor:pointer;padding:8px 0}dl{display:grid;grid-template-columns:135px minmax(0,1fr);gap:10px 18px}dt{color:#536b64}dd{margin:0;overflow-wrap:anywhere}.history{border-top:1px solid #d2ded7;padding:14px 0}.selected{border-left:3px solid #205a4d;padding-left:16px}@media(max-width:600px){main{padding:24px 16px}h1{font-size:30px}.card,.version{padding:18px}dl{grid-template-columns:1fr;gap:6px}dd{margin-bottom:10px}}`;

export function acceptancePage(value:z.output<typeof acceptanceBasisView>){
  const nonce=randomBytes(18).toString('base64url');
  const json=JSON.stringify(value).replaceAll('<','\\u003c').replaceAll('>','\\u003e').replaceAll('&','\\u0026').replaceAll('\u2028','\\u2028').replaceAll('\u2029','\\u2029');
  return {policy:`default-src 'none'; script-src 'nonce-${nonce}'; style-src 'nonce-${nonce}'; connect-src 'self'; frame-src 'none'; frame-ancestors 'self'; base-uri 'none'; object-src 'none'; worker-src 'none'; form-action 'none'`,html:`<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>版本接受 · DevMesh</title><style nonce="${nonce}">${css}</style></head><body><div id="root"><main><h1>版本接受</h1><p>正在加载固定接受依据…</p><noscript>请启用JavaScript查看与确认接受。</noscript></main></div><script id="acceptance-data" type="application/json" nonce="${nonce}">${json}</script><script defer nonce="${nonce}" src="/api/v1/runs/${encodeURIComponent(value.runId)}/candidates/${encodeURIComponent(value.candidateId)}/acceptance/client.js"></script></body></html>`};
}
